function HeroPanel({ player, isEnemy, targetable, attackable, onClick, bgColor }) {
  const highlighted = targetable || attackable;
  const hpFrac = Math.max(0, Math.min(1, player.health / player.maxHealth));
  const barH = 58;
  const redH = Math.round(barH * (1 - hpFrac));
  const greenH = barH - redH;
  return (
    <div
      onClick={onClick}
      style={{
        display: "flex", alignItems: "center", gap: 8, width: 210, minWidth: 210, height: 84, minHeight: 84, boxSizing: "border-box",
        border: `2px solid ${highlighted ? "#c0392b" : "#000"}`, borderRadius: 8, padding: "8px 10px",
        background: bgColor || "#fff", cursor: onClick ? "pointer" : "default", fontFamily: FONT,
        boxShadow: highlighted ? "0 0 0 2px #c0392b" : "1px 1px 0 rgba(0,0,0,0.12)",
        animation: attackable ? "heroAttackGlow 1.3s ease-in-out infinite" : "none",
      }}
    >
      <div style={{ width: 9, minWidth: 9, height: barH, border: "1px solid #000", borderRadius: 3, overflow: "hidden", flexShrink: 0, display: "flex", flexDirection: "column" }} title="HP">
        <div style={{ height: redH, background: "#c0392b" }} />
        <div style={{ height: greenH, background: "#2ecc71" }} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <MarqueeText text={player.displayName ? `${player.hero} ${player.displayName}` : player.hero} width="100%" fontSize={12} bold duration={7} />
        <div style={{ fontSize: 9.5, whiteSpace: "nowrap" }}>
          HP: {Math.max(0, player.health)}{player.armor > 0 ? ` (+${player.armor})` : ""}
        </div>
        <div style={{ fontSize: 9.5, marginTop: 1, display: "flex", gap: 8, whiteSpace: "nowrap" }}>
          <span>AP: {player.mana}/{player.maxMana}</span>
          <span>Deck: {player.deck.length}</span>
        </div>
        <div style={{ display: "flex", gap: 2, marginTop: 3 }} title={`${player.mana} AP available`}>
          {Array.from({ length: 10 }).map((_, i) => {
            const filled = i < player.mana;
            return (
              <div
                key={i}
                style={{
                  width: 6.5, height: 6.5, borderRadius: "50%", flexShrink: 0,
                  background: filled ? "#39ff6a" : "#ccc",
                  boxShadow: filled ? "0 2px 4px rgba(57,255,106,0.7)" : "none",
                }}
              />
            );
          })}
        </div>
      </div>
      <div style={{ width: 50, height: 50, minWidth: 50, border: "1px solid #000", borderRadius: 6, background: "rgba(255,255,255,0.55)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, overflow: "hidden" }}>
        {HERO_ART_OVERRIDES[player.hero] ? (
          <img src={HERO_ART_OVERRIDES[player.hero]} alt={player.hero} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <span style={{ fontSize: 8, color: "#888" }}>IMG</span>
        )}
      </div>
    </div>
  );
}

/* ---------- ranked tiers ---------- */
const TIERS = ["Bronze", "Silver", "Gold", "Legendary"];
function currentMonthKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}
function applyMatchResult(profile, won) {
  const mk = currentMonthKey();
  const sameMonth = profile.monthKey === mk;
  const p = {
    wins: profile.wins || 0, losses: profile.losses || 0,
    winStreak: profile.winStreak || 0, lossStreak: profile.lossStreak || 0,
    tier: profile.tier || "Bronze",
    highestTier: profile.highestTier || profile.tier || "Bronze",
    monthKey: mk,
    monthWins: sameMonth ? (profile.monthWins || 0) : 0,
    monthLosses: sameMonth ? (profile.monthLosses || 0) : 0,
  };
  if (won) {
    p.wins += 1; p.monthWins += 1;
    p.winStreak += 1; p.lossStreak = 0;
    if (p.winStreak >= 5 && TIERS.indexOf(p.tier) < TIERS.length - 1) {
      p.tier = TIERS[TIERS.indexOf(p.tier) + 1];
      p.winStreak = 0;
      if (TIERS.indexOf(p.tier) > TIERS.indexOf(p.highestTier)) p.highestTier = p.tier;
    }
  } else {
    p.losses += 1; p.monthLosses += 1;
    p.lossStreak += 1; p.winStreak = 0;
    if (p.lossStreak >= 5 && TIERS.indexOf(p.tier) > 0) {
      p.tier = TIERS[TIERS.indexOf(p.tier) - 1];
      p.lossStreak = 0;
    }
  }
  return p;
}
// A player's displayed "this month" stats, adjusted for month rollover even
// if they haven't played yet this month (so it never shows stale data).
function monthStatsFor(profile) {
  const mk = currentMonthKey();
  if (!profile || profile.monthKey !== mk) return { monthWins: 0, monthLosses: 0 };
  return { monthWins: profile.monthWins || 0, monthLosses: profile.monthLosses || 0 };
}
function ratioFor(wins, losses) {
  return losses === 0 ? wins : wins / losses;
}

/* =========================================================================
   QUESTS — 5 of 10 possible quests are active each week, chosen (and their
   numeric targets randomized) by a seed derived from Eastern Time, so every
   player sees the exact same 5 quests with the exact same targets without
   needing a server or scheduled job — same seed in, same result out, always.
   Rotates every Sunday at 20:00 Eastern Time.
   ========================================================================= */
const QUEST_POOL = [
  { id: "grinder", title: "Atomic Grinder", type: "gamesPlayed", min: 25, max: 35, verb: "Play", noun: "games" },
  { id: "warrior", title: "Feared Warrior", type: "wins", min: 15, max: 20, verb: "Win", noun: "games" },
  { id: "shuffler", title: "Casino Shuffler", type: "neutralCardsPlayed", min: 500, max: 600, verb: "Play", noun: "neutral cards" },
  { id: "overpowered", title: "Overpowered", type: "uniqueCardsPlayed", min: 60, max: 80, verb: "Play", noun: "unique cards" },
  { id: "purple", title: "Purple Monster", type: "epicCardsPlayed", min: 200, max: 250, verb: "Play", noun: "epic cards" },
  { id: "medalist", title: "Wasteland Medalist", type: "tier" },
  { id: "nemesis", title: "Nemesis", type: "heroDefeats", min: 5, max: 8, randomHero: true, verb: "Defeat", noun: "times" },
  { id: "comedy", title: "Comedy Gold", type: "cardPlays", cardName: "Jim, King of Comedy", min: 10, max: 15, verb: "Play", noun: "times" },
  { id: "armored", title: "Armored", type: "armorGained", min: 150, max: 175, verb: "Gain", noun: "armor" },
  { id: "firstaid", title: "First Aid Expert", type: "healthRestored", min: 200, max: 250, verb: "Restore", noun: "health" },
];
const QUEST_BULLET_REWARD = 100;
const QUEST_COLORS = ["#fde3c4", "#e6dcf7", "#dcf3d9", "#d9ecfb", "#fbdcdc", "#fff2b3", "#d5f5f0", "#f7d9ec"];

function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function questWeekId(date = new Date()) {
  const et = new Date(date.toLocaleString("en-US", { timeZone: "America/New_York" }));
  const shifted = new Date(et.getTime() - 20 * 60 * 60 * 1000); // shift so the boundary becomes Sunday 20:00 ET
  const day = shifted.getDay();
  const sunday = new Date(shifted);
  sunday.setDate(shifted.getDate() - day);
  sunday.setHours(0, 0, 0, 0);
  const epoch = new Date(2020, 0, 1);
  return Math.floor((sunday - epoch) / (7 * 24 * 60 * 60 * 1000));
}
function selectWeeklyQuests(weekId) {
  const rng = mulberry32(weekId);
  const pool = QUEST_POOL.map((q) => ({ ...q }));
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, 5).map((q, i) => ({
    ...q,
    target: q.min !== undefined ? q.min + Math.floor(rng() * (q.max - q.min + 1)) : null,
    hero: q.randomHero ? HEROES[Math.floor(rng() * HEROES.length)] : null,
    color: QUEST_COLORS[i % QUEST_COLORS.length],
  }));
}
function questDescription(q) {
  if (q.type === "tier") return "Reach Gold rank.";
  if (q.type === "heroDefeats") return `Defeat ${q.hero} ${q.target} times.`;
  if (q.type === "cardPlays") return `Play ${q.cardName} ${q.target} times.`;
  return `${q.verb} ${q.target} ${q.noun}.`;
}
function questProgress(q, weeklyProgress, tier) {
  if (q.type === "tier") {
    const done = TIERS.indexOf(tier || "Bronze") >= TIERS.indexOf("Gold");
    return { current: done ? 1 : 0, target: 1, done };
  }
  if (q.type === "heroDefeats") {
    const current = (weeklyProgress.heroDefeats && weeklyProgress.heroDefeats[q.hero]) || 0;
    return { current, target: q.target, done: current >= q.target };
  }
  if (q.type === "cardPlays") {
    const current = (weeklyProgress.cardPlays && weeklyProgress.cardPlays[q.cardName]) || 0;
    return { current, target: q.target, done: current >= q.target };
  }
  const current = weeklyProgress[q.type] || 0;
  return { current, target: q.target, done: current >= q.target };
}
// Fresh/rolled-over weekly progress bucket for a given weekId.
function freshWeeklyProgress(weekId) {
  return { weekId, gamesPlayed: 0, wins: 0, neutralCardsPlayed: 0, epicCardsPlayed: 0, uniqueCardsPlayed: 0, armorGained: 0, healthRestored: 0, heroDefeats: {}, cardPlays: {}, claimedQuestIds: [] };
}
function weeklyProgressFor(profile) {
  const wk = questWeekId();
  if (!profile || !profile.weeklyProgress || profile.weeklyProgress.weekId !== wk) return freshWeeklyProgress(wk);
  return profile.weeklyProgress;
}

const TIER_STYLES = {
  Bronze: { gradient: "linear-gradient(160deg, #e0a868, #9c5f22)", glow: "0 6px 18px rgba(180,110,40,0.5)", text: "#3a2308" },
  Silver: { gradient: "linear-gradient(160deg, #f2f2f2, #a8a8a8)", glow: "0 6px 18px rgba(170,170,170,0.55)", text: "#2b2b2b" },
  Gold: { gradient: "linear-gradient(160deg, #ffe38a, #c99a2e)", glow: "0 6px 18px rgba(255,205,60,0.6)", text: "#3a2a00" },
  Legendary: { gradient: "linear-gradient(160deg, #f7c8ff, #8a2be2)", glow: "0 6px 22px rgba(150,50,230,0.65)", text: "#fff" },
};

function TierFrame({ profile }) {
  const tier = profile.tier || "Bronze";
  const style = TIER_STYLES[tier];
  const isTop = tier === "Legendary";
  const onLossStreak = (profile.lossStreak || 0) > 0;
  const canDemote = TIERS.indexOf(tier) > 0;
  return (
    <div style={{ background: style.gradient, boxShadow: style.glow, borderRadius: 12, border: "2px solid #000", padding: "16px 18px", textAlign: "center", color: style.text, marginTop: 14 }}>
      <div style={{ fontSize: 11, opacity: 0.85, letterSpacing: 1 }}>YOUR TIER</div>
      <div style={{ fontSize: 26, fontWeight: 700, letterSpacing: 1 }}>{tier}</div>
      {!isTop && !onLossStreak && (
        <div style={{ fontSize: 12, marginTop: 6 }}>
          {5 - (profile.winStreak || 0)} more win{5 - (profile.winStreak || 0) === 1 ? "" : "s"} in a row to reach {TIERS[TIERS.indexOf(tier) + 1]}
        </div>
      )}
      {onLossStreak && canDemote && (
        <div style={{ fontSize: 12, marginTop: 6, fontWeight: 700, color: "#7a1010" }}>
          {5 - profile.lossStreak} more loss{5 - profile.lossStreak === 1 ? "" : "es"} in a row and you'll drop to {TIERS[TIERS.indexOf(tier) - 1]}
        </div>
      )}
      {onLossStreak && !canDemote && (
        <div style={{ fontSize: 12, marginTop: 6 }}>Bronze is the floor — no further demotion.</div>
      )}
    </div>
  );
}

function LegendaryLeaderboard({ myUid }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [visibleCount, setVisibleCount] = useState(50);
  const CAP = 250;

  useEffect(() => {
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "users"), where("tier", "==", "Legendary"), limit(500)));
        const list = snap.docs.map((d) => {
          const data = d.data();
          const { monthWins, monthLosses } = monthStatsFor(data);
          return { id: d.id, displayName: data.displayName || "Player", monthWins, monthLosses, ratio: ratioFor(monthWins, monthLosses) };
        });
        list.sort((a, b) => b.ratio - a.ratio || b.monthWins - a.monthWins);
        setRows(list.slice(0, CAP));
      } catch (e) {
        console.error("Legendary leaderboard load failed:", e);
      }
      setLoading(false);
    })();
  }, []);

  const myRankIdx = rows.findIndex((r) => r.id === myUid);
  const visible = rows.slice(0, visibleCount);
  const canShowMore = visibleCount < rows.length;

  return (
    <div style={{ marginTop: 16, background: "linear-gradient(165deg, #eafeff, #bdeeff 45%, #59c8f5)", boxShadow: "0 0 26px rgba(89,200,245,0.7)", border: "2px solid #0a7fb0", borderRadius: 12, padding: 16 }}>
      <div style={{ fontWeight: 700, fontSize: 15, textAlign: "center", color: "#043a52" }}>⬦ Legendary League — This Month ⬦</div>
      {loading ? (
        <p style={{ fontSize: 12, textAlign: "center" }}>Loading...</p>
      ) : rows.length === 0 ? (
        <p style={{ fontSize: 12, textAlign: "center", color: "#043a52" }}>No Legendary players yet this month.</p>
      ) : (
        <>
          {myRankIdx !== -1 && (
            <div style={{ fontSize: 12, fontWeight: 700, textAlign: "center", margin: "8px 0", color: "#043a52" }}>
              YOUR CURRENT RANK: #{myRankIdx + 1}
            </div>
          )}
          <table style={{ width: "100%", fontSize: 12, borderCollapse: "collapse", marginTop: 8, background: "rgba(255,255,255,0.6)", borderRadius: 6 }}>
            <thead>
              <tr style={{ textAlign: "left", borderBottom: "2px solid #0a7fb0" }}>
                <th style={{ padding: "4px 6px" }}>#</th>
                <th style={{ padding: "4px 6px" }}>Player</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>W</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>L</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>Ratio</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((r, i) => (
                <tr key={r.id} style={{ borderTop: "1px solid #bcdff0", fontWeight: r.id === myUid ? 700 : 400, background: r.id === myUid ? "rgba(10,127,176,0.15)" : "none" }}>
                  <td style={{ padding: "4px 6px" }}>{i + 1}</td>
                  <td style={{ padding: "4px 6px" }}>{r.displayName}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.monthWins}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.monthLosses}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.ratio.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {canShowMore && (
            <div style={{ textAlign: "center", marginTop: 10 }}>
              <button
                onClick={() => setVisibleCount((v) => Math.min(v + 50, CAP))}
                style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #0a7fb0", background: "#fff", color: "#043a52", cursor: "pointer", borderRadius: 4, fontWeight: 700 }}
              >
                Show More
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

